local _, WFJ = ...
WFJ.Data.add("book", {
  ["7c0b2931c91483f6"] = { "Titanの造形者にして世界の鍛え手であるKhaz'gorothは、強大な黒竜Neltharionに自らの広大な力の一部を授けた。気高い心を持つNeltharionは、以後Earth-Warderとして知られ、大地と世界の深き場所を統べる力を与えられた。彼は世界の力そのものを体現し、Alexstraszaの最大の支持者として仕えた。", "." },
  ["7c18a5979f6649c5"] = { "魔法の力を与えるエネルギーに依存するようになっていたIllidanは、再びWellのエネルギーを引き出したいという、ほとんど抗いがたい渇望を抑えようと苦しんだ。しかしTyrandeの辛抱強い支えにより、彼は自制し、兄弟が人里離れて暮らす半神Cenariusを見つける手助けをすることができた。", "." },
  ["7c586c0fe45720ea"] = { "Solid Crystal Leg Shafts -\n\nSearing GorgeのGlassweb spiderは、驚くべき水晶のような物質でできている。倒すときに傷つけなければ、その脚は仲間たちの工学実験ですばらしい導体になるんだ。\n\n試験用にいくつか必要だ。クモには脚が8本もあるんだから、頑強なウォリアーや熟練のメイジなら何の問題もないだろう。", "." },
  ["7c5f07d24bd6947c"] = { "--16日目\nUlegとThargilがTheramoreの港での任務から戻った。港に新しい船が入っていたという。Bleeding Sparrow号だ。船はAzerothのMenethil Harborから来た。\n\n明日、UlegとThargilは再び港へ行き、その船に忍び込む。TheramoreとAllianceの関係を明らかにする政治文書を見つけたいと考えている。", "." },
  ["7ca51ae5f03eeed7"] = { "War of the Ancientsとして知られるこの恐ろしい戦いの終わりに、Well of Eternityは内側へと崩壊した。その結果生じた衝撃波が、Kalimdorの広大な陸地を粉々にした。大陸の中心は海の底へと吹き飛ばされ、あとには砕けた小さな大陸がいくつか残るのみであった。", "." },
  ["7cc0016138044a58"] = { "ドルイドたちは、これほど多くの同族を死に処することはどうしてもできなかった。そこで、無謀なHighborneを自らの地から追放することに決めた。保守的な同族からようやく解放されることを喜んだDath'Remarとその信奉者たちは、特別に造られた何隻もの船に乗り込み、海へと漕ぎ出した。荒れ狂うMaelstromの海の彼方に何が待つのか誰一人知らなかったが、彼らは渇望する魔法を咎められることなく使える、自分たちの故郷を築くことを強く望んでいた。", "." },
  ["7cc905de47945c33"] = { "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align=\"center\">STRANGLETHORNの緑の丘</H1>\n<BR/>\n<H3 align=\"center\">Hemet Nesingwary 著</H3>\n</BODY>\n</HTML>", "." },
  ["7ce1ee0140c3e9bf"] = { "自分がSargerasの計画どおりに動いてしまったことを、Aegwynnが知ることは決してなかった。彼女は知らず知らずのうちに定命の世界の運命を決定づけてしまったのである。Sargerasは肉体が死を迎えたその時、自らの魂を弱ったAegwynnの体へと移していたからだ。若いGuardianが知らぬまま、Sargerasは長い年月にわたり、彼女の魂の最も暗い奥底に身を潜め続けることとなる。", "." },
  ["7cfa5ad3ef64044a"] = { "ご挨拶申し上げます、ご主人様\n\nこのような方法で書状をお送りすることをお許しください。Alteracにいる私の闇のメイジたちは任務にかかりきりで、この報告をお届けするには、我らの新たな「同盟者」から徴用した異国の使者を使わざるを得ないのです。ですが、この書状は我らの最も秘奥の暗号の一つで暗号化してあります。その言葉が、あの田舎者どもに知られることはありません。", "." },
  ["7cfcedd83295c13e"] = { "奇妙なことに、Morganthは彼らの忌まわしい勝利の直後、オークの仲間たちに背を向けた。そのウォーロックは北東に秘術の塔を築き、その力を用いて、己の悪意ある命令に従うShadowhide Gnollsの小さな軍勢を作り上げた。オークもManも、ウォーロックに仕える獰猛な獣どもの犠牲となってきた。MorganthとBlackrock WarlordたるGath'Ilzoggの間でいかなる裏切りがあったのかについては、現時点では推測するほかない。", "." },
})
